fields.InputDefinition:
{
  "goal": "Do the shared setup ONCE: open the Chat application and wait for the workspace to load. Then walk these sections IN ORDER, and as you arrive at each one set \"checkpointReached\" to the exact checkpoint name shown: (1) collections-tab — click the 'Collections' tab in the top navigation and confirm the main area switches to the collections full view (a breadcrumb starting at 'Collections' home, a grid/list view-mode toggle button, and either collection/artifact cards or a valid empty state); (2) tasks-tab — click the 'Tasks' tab in the top navigation and confirm the main area switches to the tasks full view showing task cards/widgets with status and progress OR a valid no-tasks empty state. Keep going until both sections have been visited. Pages can take 10-30s to load in this resource-constrained environment — wait for content rather than navigating away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "finalUrlPattern": "^http://localhost:4200",
  "minConfidence": 0.7,
  "maxSteps": 45,
  "checkpoints": [
    {
      "name": "collections-tab",
      "instruction": "Collections full view renders",
      "visualCriteria": [
        "The Collections tab swaps the main area to the collections full view with a 'Collections' breadcrumb/home and a grid/list view-mode toggle, and collection/artifact content renders OR a valid empty state is shown"
      ]
    },
    {
      "name": "tasks-tab",
      "instruction": "Tasks full view renders",
      "visualCriteria": [
        "The Tasks tab swaps the main area to the tasks full view where task widgets/cards render with status/progress OR a clear no-tasks empty state is shown, and the view is stable"
      ]
    },
    {
      "name": "active-tasks-dropdown",
      "instruction": "tasks dropdown in nav opens",
      "visualCriteria": [
        "A tasks dropdown control in the top navigation opens when clicked, showing active/recent tasks or a valid empty state, and closes cleanly when dismissed"
      ]
    }
  ]
}
